// ============================================================================
// EVALUACIÓN DE REGLAS DE NEGOCIO POO CON HERENCIA Y POLIMORFISMO
// ============================================================================

try {
  class EntidadComercial {
    constructor(nombre, cedula, correo = '') {
      this.nombre = nombre || '';
      this.cedula = cedula || '';
      this.correo = correo || '';
      this.email = this.correo;
    }

    obtenerIdentificacion() {
      if (!this.cedula || !this.cedula.trim()) {
        return `${this.nombre || 'Sin Nombre'} [SIN CÉDULA REGISTRADA]`;
      }
      return `${this.nombre} (ID: ${this.cedula.trim()}) <${this.correo}>`;
    }

    esIdentificacionValida() {
      return Boolean(this.cedula && this.cedula.toString().trim().length > 0);
    }
  }

  class Proveedor extends EntidadComercial {
    constructor(nombre, cedula, estadoHacienda = null, nivelRiesgo = null, correo = '') {
      super(nombre, cedula, correo);
      this.estadoHacienda = estadoHacienda;
      this.nivelRiesgo = nivelRiesgo;
    }

    procesarPagoEspecifico(montoBase) {
      throw new Error('Método abstracto procesarPagoEspecifico() debe implementarse en la subclase.');
    }

    generarClavePago(idPago = '000', fecha = new Date().toISOString().split('T')[0]) {
      const anio = fecha ? (new Date(fecha).getFullYear() || 2026) : 2026;
      const randomHex = Math.random().toString(36).substring(2, 6).toUpperCase();
      return `REF-${anio}-PAY-${idPago}-${randomHex}`;
    }

    generarPayloadQR(montoFinal, clavePago, fecha, detalle = '') {
      const ref = clavePago || this.generarClavePago('000', fecha);
      return `CLAVE: ${ref} | PROVEEDOR: ${this.nombre} | CEDULA: ${this.cedula} | MONTO_NETO: CRC ${Number(montoFinal).toFixed(2)} | FECHA: ${fecha} | CONCEPTO: ${detalle}`;
    }

    evaluarRiesgo() {
      if (this.estadoHacienda === 'Desconocido') {
        this.nivelRiesgo = 'Alto';
        return { esRiesgoso: true, motivo: 'Error de conexión con Hacienda - Revisión manual' };
      }
      if (!this.estadoHacienda || this.estadoHacienda.trim() === '') {
        this.nivelRiesgo = 'Alto';
        return { esRiesgoso: true, motivo: 'Validación tributaria obligatoria pendiente ante Hacienda' };
      }
      const norm = this.estadoHacienda.trim().toLowerCase();
      if (norm === 'moroso') {
        this.nivelRiesgo = 'Alto';
        return { esRiesgoso: true, motivo: 'Proveedor figura como Moroso ante el Ministerio de Hacienda' };
      }
      if (norm === 'al dia' || norm === 'al día') {
        this.nivelRiesgo = 'Bajo';
        return { esRiesgoso: false, motivo: 'Proveedor al día con obligaciones tributarias' };
      }
      this.nivelRiesgo = 'Alto';
      return { esRiesgoso: true, motivo: `Estado tributario no concluyente (${this.estadoHacienda})` };
    }
  }

  class ProveedorServicios extends Proveedor {
    constructor(nombre, cedula, estadoHacienda = null, nivelRiesgo = null, detalle_categoria = 'TI', porcentajeRetencion = 2, correo = '') {
      super(nombre, cedula, estadoHacienda, nivelRiesgo, correo);
      this.categoria = 'Servicios';
      this.detalle_categoria = detalle_categoria || 'Servicios Profesionales';
      this.porcentajeRetencion = Number(porcentajeRetencion) || 2;
    }

    // Polimorfismo: Resta 2% de retención de impuestos
    procesarPagoEspecifico(montoBase) {
      const bruto = Number(montoBase) || 0;
      const factor = this.porcentajeRetencion > 1 ? this.porcentajeRetencion / 100 : this.porcentajeRetencion;
      const retencion = Number((bruto * factor).toFixed(2));
      const montoFinal = Number((bruto - retencion).toFixed(2));
      return {
        montoBase: bruto,
        categoria: this.categoria,
        detalle_categoria: this.detalle_categoria,
        porcentajeRetencion: this.porcentajeRetencion,
        retencion,
        flete: 0,
        montoFinal,
        conceptoAjuste: `Retención fiscal (${this.porcentajeRetencion}%)`
      };
    }
  }

  class ProveedorBienes extends Proveedor {
    constructor(nombre, cedula, estadoHacienda = null, nivelRiesgo = null, detalle_categoria = 'Suministros', flete = 5000, correo = '') {
      super(nombre, cedula, estadoHacienda, nivelRiesgo, correo);
      this.categoria = 'Bienes';
      this.detalle_categoria = detalle_categoria || 'Suministros de oficina';
      this.flete = Number(flete) || 5000;
    }

    // Polimorfismo: Suma monto fijo de flete (CRC 5000)
    procesarPagoEspecifico(montoBase) {
      const bruto = Number(montoBase) || 0;
      const fleteMonto = Number(this.flete) || 5000;
      const montoFinal = Number((bruto + fleteMonto).toFixed(2));
      return {
        montoBase: bruto,
        categoria: this.categoria,
        detalle_categoria: this.detalle_categoria,
        porcentajeRetencion: 0,
        retencion: 0,
        flete: fleteMonto,
        montoFinal,
        conceptoAjuste: `Flete y transporte (+CRC ${fleteMonto.toLocaleString('es-CR')})`
      };
    }
  }

  class Pago {
    constructor(idPago, monto, proveedor, fecha = new Date().toISOString().split('T')[0]) {
      this.idPago = idPago;
      this.monto = Number(monto);
      this.proveedor = proveedor;
      this.fecha = fecha;
      this.estado = 'Pendiente';
      this.estadoProcesado = 'Pendiente';
      this.montoFinal = null;
      this.retencion = 0;
      this.flete = 0;
      this.calculoEspecifico = null;
      this.clavePago = null;
      this.datosParaCodificarEnQR = null;
      this.qrUrl = null;
      this.correoDestino = proveedor ? (proveedor.correo || proveedor.email) : '';
      this.emailHtml = null;
      this.motivoRetencion = null;
    }

    generarEmailHtml() {
      if (this.estado !== 'Aprobado') return '';

      const montoBrutoFmt = Number(this.monto).toLocaleString('es-CR', { minimumFractionDigits: 2 });
      const montoFinalFmt = Number(this.montoFinal).toLocaleString('es-CR', { minimumFractionDigits: 2 });
      const retencionFmt = Number(this.retencion).toLocaleString('es-CR', { minimumFractionDigits: 2 });
      const fleteFmt = Number(this.flete).toLocaleString('es-CR', { minimumFractionDigits: 2 });

      let filaAjuste = '';
      if (this.retencion > 0) {
        filaAjuste = `<tr><td style="padding:10px 16px;color:#e11d48;border-bottom:1px solid #e2e8f0;">Retención Fiscal (${this.calculoEspecifico?.porcentajeRetencion || 2}%):</td><td style="padding:10px 16px;color:#e11d48;font-weight:600;text-align:right;border-bottom:1px solid #e2e8f0;">- CRC ${retencionFmt}</td></tr>`;
      } else if (this.flete > 0) {
        filaAjuste = `<tr><td style="padding:10px 16px;color:#0284c7;border-bottom:1px solid #e2e8f0;">Cargo por Flete y Transporte:</td><td style="padding:10px 16px;color:#0284c7;font-weight:600;text-align:right;border-bottom:1px solid #e2e8f0;">+ CRC ${fleteFmt}</td></tr>`;
      }

      return `<!DOCTYPE html><html><body style="margin:0;padding:24px 10px;background:#f1f5f9;font-family:sans-serif;color:#1e293b;">
<table width="100%" border="0" align="center" style="max-width:580px;background:#fff;border:1px solid #e2e8f0;border-radius:16px;overflow:hidden;box-shadow:0 10px 25px rgba(0,0,0,0.05);">
  <tr><td style="padding:32px 28px;background:linear-gradient(135deg,#0f172a 0%,#1e293b 100%);text-align:center;">
    <div style="display:inline-block;padding:6px 14px;background:rgba(16,185,129,0.15);border:1px solid #10b981;border-radius:20px;margin-bottom:12px;">
      <span style="color:#34d399;font-size:11px;font-weight:700;text-transform:uppercase;">✔ PAGO APROBADO & VERIFICADO</span>
    </div>
    <h1 style="margin:0 0 6px;font-size:24px;font-weight:800;color:#fff;">Comprobante Oficial de Pago</h1>
    <p style="margin:0;font-size:13px;color:#94a3b8;">Sistema de Liquidación y Panel de Riesgo con Código QR</p>
  </td></tr>
  <tr><td style="padding:28px;">
    <p style="font-size:15px;color:#334155;margin:0 0 12px;">Estimado(a) <strong style="color:#0f172a;">${this.proveedor.nombre}</strong>,</p>
    <p style="font-size:13px;color:#64748b;line-height:1.5;margin:0 0 20px;">Le confirmamos que su orden de pago ha sido aprobada de conformidad con las disposiciones tributarias vigentes.</p>
    <div style="background:#f8fafc;border:1px solid #e2e8f0;border-left:4px solid #0284c7;border-radius:8px;padding:18px 16px;text-align:center;margin:20px 0;">
      <div style="font-size:11px;font-weight:800;color:#0284c7;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:6px;">🔑 CLAVE DE PAGO ÚNICA DE AUDITORÍA</div>
      <div style="font-size:24px;font-weight:900;font-family:monospace;color:#0f172a;letter-spacing:2px;">${this.clavePago}</div>
      <div style="font-size:11px;color:#64748b;margin-top:4px;">Referencia inmutable de auditoría</div>
    </div>
    <table width="100%" border="0" style="border:1px solid #e2e8f0;border-radius:12px;margin:20px 0;overflow:hidden;">
      <tr><td style="padding:10px 16px;font-size:13px;color:#64748b;border-bottom:1px solid #f1f5f9;">ID del Pago:</td><td style="padding:10px 16px;font-size:13px;font-weight:600;text-align:right;border-bottom:1px solid #f1f5f9;">${this.idPago}</td></tr>
      <tr><td style="padding:10px 16px;font-size:13px;color:#64748b;border-bottom:1px solid #f1f5f9;">Identificación / Cédula:</td><td style="padding:10px 16px;font-size:13px;font-weight:600;text-align:right;border-bottom:1px solid #f1f5f9;">${this.proveedor.cedula}</td></tr>
      <tr><td style="padding:10px 16px;font-size:13px;color:#64748b;border-bottom:1px solid #f1f5f9;">Categoría:</td><td style="padding:10px 16px;font-size:13px;font-weight:600;text-align:right;border-bottom:1px solid #f1f5f9;">${this.proveedor.categoria} (${this.proveedor.detalle_categoria})</td></tr>
      <tr><td style="padding:10px 16px;font-size:13px;color:#64748b;border-bottom:1px solid #f1f5f9;">Monto Base:</td><td style="padding:10px 16px;font-size:13px;font-weight:600;text-align:right;border-bottom:1px solid #f1f5f9;">CRC ${montoBrutoFmt}</td></tr>
      ${filaAjuste}
      <tr style="background:#f0fdf4;"><td style="padding:14px 16px;font-size:14px;font-weight:700;color:#166534;">Monto Final Liquidado:</td><td style="padding:14px 16px;font-size:18px;font-weight:900;color:#166534;text-align:right;">CRC ${montoFinalFmt}</td></tr>
    </table>
    <div style="background:#f8fafc;border:1px solid #e2e8f0;border-radius:12px;padding:22px 16px;text-align:center;margin:20px 0;">
      <div style="font-size:12px;font-weight:700;color:#475569;text-transform:uppercase;margin-bottom:6px;">Código QR de Verificación Inmutable</div>
      <p style="margin:0 0 14px;font-size:12px;color:#64748b;">Descargue el comprobante oficial adjunto o use el enlace directo.</p>
      <div style="display:inline-block;padding:10px;background:#fff;border-radius:12px;border:1px solid #cbd5e1;"><img src="${this.qrUrl}" alt="Código QR" width="200" height="200" style="display:block;margin:0 auto;" /></div>
      <div style="margin-top:16px;"><a href="${this.qrUrl}" target="_blank" style="display:inline-block;background:#0284c7;color:#fff;text-decoration:none;padding:12px 24px;font-size:13px;font-weight:700;border-radius:8px;">📥 Descargar / Guardar Comprobante QR</a></div>
    </div>
  </td></tr>
  <tr><td style="padding:16px;background:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;font-size:11px;color:#94a3b8;">© 2026 Panel de Riesgo de Proveedores - Laboratorio 1</td></tr>
</table>
</body></html>`;
    }

    procesarPago() {
      if (!this.proveedor || !this.proveedor.cedula || !this.proveedor.cedula.toString().trim()) {
        this.estado = 'Error de validacion';
        this.estadoProcesado = this.estado;
        this.motivoRetencion = 'Cédula de proveedor faltante o nula.';
        return this;
      }
      if (isNaN(this.monto) || this.monto <= 0) {
        this.estado = 'Error de validacion';
        this.estadoProcesado = this.estado;
        this.motivoRetencion = `Monto inválido (${this.monto}). Debe ser mayor a 0.`;
        return this;
      }
      if (this.proveedor.estadoHacienda === 'Desconocido') {
        this.estado = 'Retenido';
        this.estadoProcesado = this.estado;
        this.motivoRetencion = 'Error de conexión con Hacienda - Revisión manual';
        return this;
      }
      if (!this.proveedor.estadoHacienda || this.proveedor.estadoHacienda.trim() === '') {
        this.estado = 'Retenido';
        this.estadoProcesado = this.estado;
        this.motivoRetencion = 'Validación tributaria obligatoria pendiente ante Hacienda.';
        return this;
      }

      const riesgo = this.proveedor.evaluarRiesgo();
      if (riesgo.esRiesgoso) {
        this.estado = 'Retenido';
        this.estadoProcesado = this.estado;
        this.motivoRetencion = riesgo.motivo;
        return this;
      }

      this.estado = 'Aprobado';
      this.estadoProcesado = this.estado;

      // Reto 1: Polimorfismo Real
      this.calculoEspecifico = this.proveedor.procesarPagoEspecifico(this.monto);
      this.montoFinal = this.calculoEspecifico.montoFinal;

      this.retencion = this.calculoEspecifico.retencion || 0;
      this.flete = this.calculoEspecifico.flete || 0;

      this.clavePago = this.proveedor.generarClavePago(this.idPago, this.fecha);
      this.datosParaCodificarEnQR = this.proveedor.generarPayloadQR(
        this.montoFinal,
        this.clavePago,
        this.fecha,
        this.proveedor.detalle_categoria
      );
      this.qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(this.datosParaCodificarEnQR)}`;
      this.correoDestino = this.proveedor.correo || 'lmendezpozo@gmail.com';
      this.emailHtml = this.generarEmailHtml();

      return this;
    }

    toObjeto() {
      return {
        idPago: this.idPago,
        id: this.idPago,
        estadoProcesado: this.estadoProcesado,
        estado: this.estado,
        clavePago: this.clavePago,
        datosParaCodificarEnQR: this.datosParaCodificarEnQR,
        datosParaQR: this.datosParaCodificarEnQR,
        correoDestino: this.correoDestino,
        montoBase: this.monto,
        monto: this.monto,
        montoFinal: this.montoFinal,
        montoNeto: this.montoFinal,
        retencion: this.retencion,
        flete: this.flete,
        calculoEspecifico: this.calculoEspecifico,
        motivoRetencion: this.motivoRetencion,
        qrUrl: this.qrUrl,
        emailHtml: this.emailHtml,
        fecha: this.fecha,
        proveedor: {
          nombre: this.proveedor ? this.proveedor.nombre : '',
          cedula: this.proveedor ? this.proveedor.cedula : '',
          correo: this.proveedor ? this.proveedor.correo : '',
          categoria: this.proveedor ? this.proveedor.categoria : '',
          detalle_categoria: this.proveedor ? this.proveedor.detalle_categoria : '',
          estadoHacienda: this.proveedor ? this.proveedor.estadoHacienda : null,
          nivelRiesgo: this.proveedor ? this.proveedor.nivelRiesgo : null
        }
      };
    }
  }

  // EXTRACCIÓN DE ENTRADA
  const input = $input.first().json;
  const pagoData = input.pago || input;
  const provData = pagoData.proveedor || {};
  const estadoHacienda = input.estadoHacienda || provData.estadoHacienda || 'Desconocido';

  const categoria = (pagoData.categoria || provData.categoria || 'Servicios').toString().trim().toLowerCase();
  const detalleCategoria = pagoData.detalle_categoria || provData.detalle_categoria || 'General';
  const correo = pagoData.correo || provData.correo || 'lmendezpozo@gmail.com';

  let proveedorInstancia;
  if (categoria === 'bienes') {
    const flete = Number(pagoData.flete || provData.flete) || 5000;
    proveedorInstancia = new ProveedorBienes(
      provData.nombre || pagoData.nombre,
      provData.cedula || pagoData.cedula,
      estadoHacienda,
      null,
      detalleCategoria,
      flete,
      correo
    );
  } else {
    const retPct = Number(pagoData.porcentajeRetencion || provData.porcentajeRetencion) || 2;
    proveedorInstancia = new ProveedorServicios(
      provData.nombre || pagoData.nombre,
      provData.cedula || pagoData.cedula,
      estadoHacienda,
      null,
      detalleCategoria,
      retPct,
      correo
    );
  }

  const pagoInstancia = new Pago(
    pagoData.idPago || pagoData.id || 'PAG-000',
    pagoData.monto,
    proveedorInstancia,
    pagoData.fecha || new Date().toISOString().split('T')[0]
  );

  pagoInstancia.procesarPago();

  return [{
    json: {
      ok: true,
      data: pagoInstancia.toObjeto(),
      error: null
    }
  }];
} catch (error) {
  return [{
    json: {
      ok: false,
      data: null,
      error: error.message || 'Error en evaluación POO'
    }
  }];
}
